import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

// .github/dependabot.yml is generated from templates.json, because vendored
// templates (entries with a source) must not get Dependabot security PRs:
// their code changes only through upstream syncs.
//
// Dependabot has no way to drop one directory from a "/templates/*" glob.
// exclude-paths is "Version updates only", and a directory missing from
// dependabot.yml still gets security updates with default settings. What does
// apply to security updates is `ignore`, so the vendored directories get their
// own npm entry that ignores every dependency, and every other template is
// listed by name in the entry that groups security updates.
//
//   dependabot-config.mjs           exit 1 if dependabot.yml is out of date
//   dependabot-config.mjs --write   regenerate it

export const DEPENDABOT_FILE = '.github/dependabot.yml';

export function renderDependabotConfig({ maintained, vendored }) {
  const list = (ids) => ids.map((id) => `      - "/templates/${id}"`).join('\n');
  const lines = [
    '# Generated by .github/scripts/dependabot-config.mjs from templates.json.',
    '# Do not edit by hand: run `node .github/scripts/dependabot-config.mjs --write`.',
    'version: 2',
    'updates:',
    '  - package-ecosystem: npm',
    '    directories:',
    list(maintained),
    '    schedule:',
    '      interval: daily',
    '    # Version updates off. Security updates stay on and are grouped so',
    '    # one advisory opens one PR across every matching template.',
    '    open-pull-requests-limit: 0',
    '    groups:',
    '      security:',
    '        applies-to: security-updates',
    '        patterns:',
    '          - "*"',
    '        update-types:',
    '          - minor',
    '          - patch',
  ];
  if (vendored.length) {
    lines.push(
      '  # Vendored templates: copies of an upstream repository, updated only by',
      '  # upstream syncs. Ignoring every dependency stops security PRs too.',
      '  - package-ecosystem: npm',
      '    directories:',
      list(vendored),
      '    schedule:',
      '      interval: daily',
      '    open-pull-requests-limit: 0',
      '    ignore:',
      '      - dependency-name: "*"',
    );
  }
  return `${lines.join('\n')}\n`;
}

// Template folders with a package.json, split by whether templates.json gives
// them a source.
export function templateDirectories(root = '.') {
  const catalog = JSON.parse(readFileSync(join(root, 'templates.json'), 'utf8'));
  const vendoredIds = new Set((catalog.templates ?? []).filter((entry) => entry.source).map((entry) => entry.id));
  const ids = readdirSync(join(root, 'templates'), { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && existsSync(join(root, 'templates', entry.name, 'package.json')))
    .map((entry) => entry.name)
    .sort();
  return {
    maintained: ids.filter((id) => !vendoredIds.has(id)),
    vendored: ids.filter((id) => vendoredIds.has(id)),
  };
}

// npm entries of a dependabot.yml: their directories and whether they ignore
// every dependency. A line-based reader, not YAML: it handles the block style
// renderDependabotConfig writes, which is all the checks need.
export function parseNpmEntries(text) {
  const entries = [];
  let entry = null;
  let block = null;
  let blockIndent = -1;
  let ignoreItem = null;
  const closeIgnoreItem = () => {
    if (ignoreItem && entry && ignoreItem.keys.length === 1 && ignoreItem.name === '*') {
      entry.ignoresAll = true;
    }
    ignoreItem = null;
  };
  for (const line of text.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }
    const indent = line.search(/\S/);
    const ecosystem = trimmed.match(/^-\s*package-ecosystem:\s*(.+)$/);
    if (ecosystem) {
      closeIgnoreItem();
      block = null;
      entry = { ecosystem: unquote(ecosystem[1]), directories: [], ignoresAll: false };
      entries.push(entry);
      continue;
    }
    if (!entry) {
      continue;
    }
    if (block && indent <= blockIndent) {
      closeIgnoreItem();
      block = null;
    }
    if (block === 'directories' && trimmed.startsWith('- ')) {
      entry.directories.push(unquote(trimmed.slice(2)));
      continue;
    }
    if (block === 'ignore') {
      const item = trimmed.match(/^(-\s+)?([\w-]+):\s*(.*)$/);
      if (item?.[1]) {
        closeIgnoreItem();
        ignoreItem = { keys: [], name: null };
      }
      if (item && ignoreItem) {
        ignoreItem.keys.push(item[2]);
        if (item[2] === 'dependency-name') {
          ignoreItem.name = unquote(item[3]);
        }
      }
      continue;
    }
    const directory = trimmed.match(/^directory:\s*(.+)$/);
    if (directory) {
      entry.directories.push(unquote(directory[1]));
    } else if (/^(directories|ignore):\s*$/.test(trimmed)) {
      block = trimmed.replace(/:\s*$/, '');
      blockIndent = indent;
    }
  }
  closeIgnoreItem();
  return entries.filter((item) => item.ecosystem === 'npm');
}

function unquote(value) {
  return value
    .replace(/\s+#.*$/, '')
    .trim()
    .replace(/^(['"])(.*)\1$/, '$2');
}

// Dependabot globs: "*" stays within one path segment, "**" crosses them.
export function globMatches(pattern, path) {
  const normalize = (value) => `/${value.replace(/^\/+|\/+$/g, '')}`;
  const source = normalize(pattern)
    .split(/(\*\*|\*)/)
    .map((part) => (part === '**' ? '.*' : part === '*' ? '[^/]*' : part.replace(/[.+?^${}()|[\]\\]/g, '\\$&')))
    .join('');
  return new RegExp(`^${source}$`).test(normalize(path));
}

// Why Dependabot could open security PRs for templates/<id>/, or null when
// only npm entries that ignore every dependency list it.
export function vendoredExclusionProblem(text, id) {
  const path = `/templates/${id}`;
  const covering = parseNpmEntries(text).filter((entry) => entry.directories.some((pattern) => globMatches(pattern, path)));
  if (!covering.length) {
    return `${DEPENDABOT_FILE} does not list ${path}, and Dependabot opens security PRs for unlisted directories; add it to the npm entry that ignores "*"`;
  }
  const open = covering.filter((entry) => !entry.ignoresAll);
  if (open.length) {
    const patterns = open.flatMap((entry) => entry.directories.filter((pattern) => globMatches(pattern, path)));
    return `${DEPENDABOT_FILE} scans ${path} through ${patterns.map((pattern) => `"${pattern}"`).join(', ')} in an npm entry that does not ignore "*"`;
  }
  return null;
}

function main() {
  const expected = renderDependabotConfig(templateDirectories('.'));
  if (process.argv.includes('--write')) {
    writeFileSync(DEPENDABOT_FILE, expected);
    console.log(`Wrote ${DEPENDABOT_FILE}.`);
    return;
  }
  const actual = existsSync(DEPENDABOT_FILE) ? readFileSync(DEPENDABOT_FILE, 'utf8') : '';
  if (actual !== expected) {
    console.log(`::error file=${DEPENDABOT_FILE}::${DEPENDABOT_FILE} is out of date. Run: node .github/scripts/dependabot-config.mjs --write`);
    process.exit(1);
  }
  console.log(`${DEPENDABOT_FILE} is up to date.`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}
